const SIZES = {
  sm: 48,
  md: 96,
  lg: 160,
} as const;

type LoaderSize = keyof typeof SIZES;

interface AdscaleLoaderProps {
  /** Rendered diameter in px. sm = inline (derivation card), lg = page-level. */
  size?: LoaderSize;
  /** Accessible label announced to screen readers. */
  label?: string;
  className?: string;
}

const loop = (duration = LOOP_DURATION) => ({
  duration,
  ease: EASE,
  repeat: Infinity,
});

export function AdscaleLoader({
  size = "md",
  label = "Carregando",
  className,
}: AdscaleLoaderProps) {
  const reduced = useReducedMotion();
  const px = SIZES[size];
  const glowId = useId();

  return (
    <m.svg
      role="img"
      aria-label={label}
      viewBox="0 0 1080 1080"
      width={px}
      height={px}
      style={{ overflow: "visible", transformOrigin: "center" }}
      className={className}
      animate={reduced ? undefined : { scale: [0.94, 1.05, 0.94] }}
      transition={reduced ? undefined : loop()}
    >
      <defs>
        <filter id={glowId} x="-50%" y="-50%" width="200%" height="200%">
          <feGaussianBlur stdDeviation={reduced ? 6 : 7} result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>

      {/* Brand monogram outline (static anchor) */}
      <g
        fill="none"
        stroke={ACCENT}
        strokeWidth={6}
        vectorEffect="non-scaling-stroke"
        opacity={reduced ? 0.22 : undefined}
      >
        <m.path
          d={OUTLINE_PATH_1}
          animate={reduced ? undefined : { strokeOpacity: [0.16, 0.28, 0.16] }}
          transition={reduced ? undefined : loop()}
        />
      </g>

      {/* Travelling dash along the contour */}
      <m.path
        d={CONTOUR_PATH}
        fill="none"
        stroke={ACCENT}
        strokeWidth={11}
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeDasharray="95 905"
        vectorEffect="non-scaling-stroke"
        filter={`url(#${glowId})`}
        animate={
          reduced
            ? undefined
            : {
                strokeDashoffset: [0, -1000],
                strokeWidth: [9, 13, 9],
              }
        }
        transition={reduced ? undefined : loop()}
      />
    </m.svg>
  );
}

/** Convenience wrapper that centers the loader in a flex region. */
export function AdscaleLoaderStage({
  size = "lg",
  label,
  className,
}: AdscaleLoaderProps) {
  return (
    <div
      className={cn(
        "flex min-h-[60vh] w-full items-center justify-center",
        className
      )}
    >
      <AdscaleLoader size={size} label={label} />
    </div>
  );
}
